// THERMA-X100 service worker — offline-first application shell, network-first live data with
// cached fallback, periodic background refresh of live data. Generated by tools/build.mjs; do not edit sw.js.
const VERSION = '__VERSION__';
const APP = 'tx-app-' + VERSION, DATA = 'tx-data-v1';
const PRECACHE = __FILES__;

self.addEventListener('install', (e) => {
  e.waitUntil((async () => { const c = await caches.open(APP); await c.addAll(PRECACHE.map(f => new Request(f, { cache: 'reload' }))); })());
});
self.addEventListener('activate', (e) => {
  e.waitUntil((async () => { for (const k of await caches.keys()) if (k.startsWith('tx-app-') && k !== APP) await caches.delete(k); await self.clients.claim(); })());
});
self.addEventListener('message', (e) => { if (e.data === 'skipWaiting') self.skipWaiting(); if (e.data === 'refreshLive') e.waitUntil?.(refreshLive()); });

self.addEventListener('fetch', (e) => {
  const req = e.request; if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin === location.origin) {
    if (req.mode === 'navigate') { e.respondWith(caches.match('./index.html').then(r => r || fetch(req)).catch(() => caches.match('./index.html'))); return; }
    e.respondWith((async () => { const c = await caches.open(APP); const hit = await c.match(req, { ignoreSearch: true }); const net = fetch(req).then(r => { if (r.ok) c.put(req, r.clone()); return r; }).catch(() => null); return hit || (await net) || new Response('Offline', { status: 503 }); })());
    return;
  }
  // cross-origin live data: network first, fall back to last good copy
  e.respondWith((async () => { const c = await caches.open(DATA); try { const r = await fetch(req); if (r.ok) c.put(req, r.clone()); return r; } catch (err) { const hit = await c.match(req); if (hit) return hit; throw err; } })());
});

// Periodic background sync (installed apps on supporting browsers): re-fetch the most recently used live-data
// requests recorded by the app (weather, climatology, economics, carbon, commodity prices, literature) directly from
// the public services into the on-device cache, so the app opens with fresh data even after long periods offline.
const idb = () => new Promise((res) => { try { const r = indexedDB.open('therma-live', 1); r.onupgradeneeded = () => r.result.createObjectStore('cache'); r.onsuccess = () => res(r.result); r.onerror = () => res(null); } catch { res(null); } });
const iget = (db, k) => new Promise((r) => { try { const q = db.transaction('cache').objectStore('cache').get(k); q.onsuccess = () => r(q.result || null); q.onerror = () => r(null); } catch { r(null); } });
const iput = (db, k, v) => new Promise((r) => { try { const tx = db.transaction('cache', 'readwrite'); tx.objectStore('cache').put(v, k); tx.oncomplete = () => r(true); tx.onerror = () => r(false); } catch { r(false); } });
async function refreshLive() {
  const db = await idb(); if (!db) return; const rec = await iget(db, '__refresh'); let n = 0;
  for (const e of rec?.list || []) { try { const r = await fetch(e.url, { headers: e.text ? {} : { Accept: 'application/json' } }); if (!r.ok) continue; const data = e.text ? await r.text() : await r.json(); await iput(db, e.url, { t: Date.now(), data }); n++; } catch { /* next */ } }
  return n;
}
self.addEventListener('periodicsync', (e) => { if (e.tag === 'tx-refresh') e.waitUntil(refreshLive()); });
